"""Parity probe tests (T04 adapted: real path src/heart/reporting/data_methods/parity.py)."""
import sqlite3
from pathlib import Path

import pytest

from heart.config import EXPERIMENTS_DIR
from heart.eval.treatment_declared import GATE_METRIC, GATE_MIN_DELTA_ROC_AUC, PAIRED_SIGNIFICANCE_ALPHA, gate_text
from heart.reporting.data_methods import parity as parity_mod
from heart.tracking.mlflow_store import DEFAULT_EXPERIMENT, TRACKING_DIRNAME

# The real probe (``run_parity()`` with its defaults) reads the real MLflow tracking
# store, which is deliberately gitignored evidence (regenerated by ``make reproduce``)
# and therefore absent in a fresh CI checkout. Gate the one real-store node the same
# way ``tests/test_app_e2e.py`` gates the real artifact: run for real when the
# populated store is present, skip with a named reason when it is not. The check is a
# read-only sqlite probe because opening the store through MLflow would *create* an
# empty database file as a side effect of deciding whether it exists.
_REAL_STORE = EXPERIMENTS_DIR / TRACKING_DIRNAME / "mlflow.db"


def _real_store_has_experiment(
    db_path: Path = _REAL_STORE, experiment: str = DEFAULT_EXPERIMENT
) -> bool:
    """True when the gitignored tracking store exists and names the experiment."""
    if not db_path.is_file():
        return False
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as con:
            row = con.execute(
                "SELECT 1 FROM experiments WHERE name = ? LIMIT 1", (experiment,)
            ).fetchone()
    except sqlite3.Error:
        return False
    return row is not None


def _real_store_has_gate_runs(db_path: Path = _REAL_STORE) -> bool:
    """True when the store holds the M006 gate evidence the real probe verifies."""
    if not db_path.is_file():
        return False
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as con:
            row = con.execute(
                "SELECT 1 FROM tags k JOIN tags v ON k.run_uuid = v.run_uuid"
                " WHERE k.key = 'run_kind' AND k.value = 'treatment-candidate'"
                " AND v.key = 'split_version' AND v.value = 'v1' LIMIT 1"
            ).fetchone()
    except sqlite3.Error:
        return False
    return row is not None


def _real_probe_skip_reason(db_path: Path = _REAL_STORE) -> str | None:
    """Why the real probe cannot run here, or None when it can."""
    if not _real_store_has_experiment(db_path):
        return (
            "Real MLflow store absent or has no 'heart-failure-prediction'"
            " experiment (gitignored evidence); run `make reproduce` to populate"
            " it, then re-run the probe."
        )
    if not _real_store_has_gate_runs(db_path):
        return (
            "Real MLflow store lacks the M006 treatment-candidate gate runs"
            " (v1 evidence was lost with the M006 worktree); regenerate with"
            " `PYTHONPATH=src python -m heart.eval.treatment_gate_real` to"
            " re-run the real probe."
        )
    return None


_REAL_PROBE_SKIP_REASON = _real_probe_skip_reason()

def test_parity_module_has_no_gsd_paths():
    text = Path(parity_mod.__file__).read_text()
    assert ".gsd/" not in text

def test_parity_checks_cover_declared_constants():
    names = {n for n in dir(parity_mod) if n.startswith("check_")}
    assert "check_alpha" in names
    assert "check_verdicts_match_store" in names
    assert hasattr(parity_mod, "run_parity")
    assert hasattr(parity_mod, "main")
    assert GATE_METRIC == "roc_auc"
    assert GATE_MIN_DELTA_ROC_AUC == 0.01
    assert 0.0 < PAIRED_SIGNIFICANCE_ALPHA < 1.0
    assert gate_text().strip() != ""

@pytest.mark.skipif(
    _REAL_PROBE_SKIP_REASON is not None, reason=_REAL_PROBE_SKIP_REASON or ""
)
def test_parity_probe_passes_on_real_reports():
    report = parity_mod.run_parity()
    assert report.measured_pair_count >= 0
    assert len(report.checks) > 0
    for check in report.checks:
        assert check.passed, "parity check failed: " + check.name + ": " + check.actual

def test_negative_mismatched_alpha_fails_loudly():
    try:
        parity_mod.check_alpha({"alpha": 999.0}, "alpha=999", "alpha=999")
    except parity_mod.ParityProbeError:
        return
    raise AssertionError("mismatched alpha should raise ParityProbeError")

def test_negative_bad_geometry_fails_loudly():
    try:
        parity_mod.check_gate_geometry({"delta": -1.0, "metric": "nope"}, [])
    except Exception:
        return
    raise AssertionError("bad geometry should fail loudly")


def _make_store(db_path: Path, experiment: "str | None") -> Path:
    with sqlite3.connect(db_path) as con:
        con.execute("CREATE TABLE experiments (name TEXT)")
        if experiment is not None:
            con.execute("INSERT INTO experiments VALUES (?)", (experiment,))
    return db_path


def test_store_gate_missing_file_is_false(tmp_path):
    assert _real_store_has_experiment(tmp_path / "absent.db") is False


def test_store_gate_unpopulated_store_is_false(tmp_path):
    assert _real_store_has_experiment(_make_store(tmp_path / "mlflow.db", None)) is False


def test_store_gate_populated_store_is_true(tmp_path):
    db = _make_store(tmp_path / "mlflow.db", DEFAULT_EXPERIMENT)
    assert _real_store_has_experiment(db) is True


def test_store_gate_other_experiment_only_is_false(tmp_path):
    db = _make_store(tmp_path / "mlflow.db", "some-other-experiment")
    assert _real_store_has_experiment(db) is False


def test_store_gate_corrupt_file_is_false(tmp_path):
    db = tmp_path / "mlflow.db"
    db.write_bytes(b"not a sqlite database at all")
    assert _real_store_has_experiment(db) is False


def _make_gate_store(db_path: Path, run_kind: str, split_version: str) -> Path:
    """Minimal MLflow-shaped store: one tags row per tag, keyed by run_uuid."""
    with sqlite3.connect(db_path) as con:
        con.execute("CREATE TABLE experiments (name TEXT)")
        con.execute("INSERT INTO experiments VALUES ('heart-failure-prediction')")
        con.execute("CREATE TABLE tags (key TEXT, value TEXT, run_uuid TEXT)")
        con.executemany(
            "INSERT INTO tags VALUES (?, ?, 'r1')",
            [("run_kind", run_kind), ("split_version", split_version)],
        )
    return db_path


def test_gate_runs_gate_missing_file_is_false(tmp_path):
    assert _real_store_has_gate_runs(tmp_path / "absent.db") is False


def test_gate_runs_gate_final_only_is_false(tmp_path):
    db = _make_gate_store(tmp_path / "mlflow.db", "final", "v1")
    assert _real_store_has_gate_runs(db) is False


def test_gate_runs_gate_candidate_other_split_is_false(tmp_path):
    db = _make_gate_store(tmp_path / "mlflow.db", "treatment-candidate", "fixture")
    assert _real_store_has_gate_runs(db) is False


def test_gate_runs_gate_candidate_v1_is_true(tmp_path):
    db = _make_gate_store(tmp_path / "mlflow.db", "treatment-candidate", "v1")
    assert _real_store_has_gate_runs(db) is True


def test_skip_reason_missing_store_names_reproduce(tmp_path):
    reason = _real_probe_skip_reason(tmp_path / "absent.db")
    assert reason is not None and "make reproduce" in reason


def test_skip_reason_missing_evidence_names_gate_command(tmp_path):
    db = _make_gate_store(tmp_path / "mlflow.db", "final", "v1")
    reason = _real_probe_skip_reason(db)
    assert reason is not None and "treatment_gate_real" in reason


def test_skip_reason_none_when_probe_prerequisites_hold(tmp_path):
    db = _make_gate_store(tmp_path / "mlflow.db", "treatment-candidate", "v1")
    assert _real_probe_skip_reason(db) is None


def test_store_gate_never_creates_the_store(tmp_path):
    """Deciding whether the store exists must not create it (CI side-effect guard)."""
    db = tmp_path / "subdir" / "mlflow.db"
    db.parent.mkdir()
    assert _real_store_has_experiment(db) is False
    assert not db.exists()
